
.wrap {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── 积蓄：放大数字 + 灰字旁注 ── */
.net {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-bottom: 16px;
  border-bottom: 0.5px solid var(--c-border);
}

.net__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.net__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
}

.net__nums {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
}

.net__v {
  font-family: var(--font-mono);
  font-size: 26px;
  font-weight: 300;
  letter-spacing: -0.035em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.net__v--ok {
  color: var(--c-text);
}

.net__v--warn {
  color: #c96a00;
}

.net__v--bad {
  color: var(--c-danger);
}

.net__cny {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.net__hint {
  margin-top: 4px;
  font-size: 11.5px;
  color: var(--c-text-muted);
  line-height: 1.6;
}

/* ── 收支：两行，用发丝线分 ── */
.flows {
  display: flex;
  flex-direction: column;
}

.flow {
  padding: 11px 0;
  border-bottom: 0.5px solid var(--c-border);

  &:first-child {
    padding-top: 0;
  }

  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
}

.flow__row {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.flow__k {
  font-size: 11px;
  color: var(--c-text-muted);
  flex-shrink: 0;
}

.flow__v {
  font-family: var(--font-mono);
  font-size: 15px;
  letter-spacing: -0.01em;
  margin-left: auto;
  font-variant-numeric: tabular-nums;
}

.flow__cycle {
  font-size: 10px;
  color: var(--c-text-faint);
  flex-shrink: 0;
  width: 20px;
  text-align: left;
}

.flow__sub {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-top: 4px;
}

.flow__cny {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--c-text-faint);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.flow__note {
  font-size: 11px;
  color: var(--c-text-faint);
  line-height: 1.5;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.block__h {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-text-faint);
  margin-bottom: 8px;
}

.prose {
  font-size: 12px;
  line-height: 1.75;
  color: var(--c-text-muted);
  white-space: pre-wrap;
}

.guard {
  font-size: 11px;
  color: var(--c-text-faint);
  line-height: 1.6;
  border-top: 0.5px solid var(--c-border);
  padding-top: 12px;
}
