
.wrap {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── 状态：极小的一行，不做成卡片 ── */
.state {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 12px;
  border-bottom: 0.5px solid var(--c-border);
}

.state__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.state__dot--ok {
  background: #34c759;
  box-shadow: 0 0 6px rgba(52, 199, 89, 0.5);
}

.state__dot--mid {
  background: #aeaeb2;
}

.state__dot--warn {
  background: #ff9500;
  box-shadow: 0 0 6px rgba(255, 149, 0, 0.5);
}

.state__dot--bad {
  background: #ff3b30;
  box-shadow: 0 0 6px rgba(255, 59, 48, 0.5);
}

.state__label {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.state__sub {
  font-size: 11px;
  color: var(--c-text-muted);
  line-height: 1.4;
}

/* ── 体重 ── */
.weight {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.weight__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.weight__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
}

.weight__v {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}

.weight__num {
  font-family: var(--font-mono);
  font-size: 30px;
  font-weight: 300;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.weight__num--empty {
  color: var(--c-text-faint);
}

.tri {
  font-size: 11px;
  line-height: 1;
  transform: translateY(-4px);
}

.tri--up {
  color: var(--c-danger);
}

.tri--down {
  color: #248a3d;
}

.weight__why {
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--c-text-muted);
}

.weight__why--empty {
  color: var(--c-text-faint);
}

.weight__daily {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
  padding-top: 7px;
  border-top: 0.5px solid var(--c-border);
  font-size: 10.5px;
  line-height: 1.5;
}

.weight__daily-k {
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
}

.weight__daily-v {
  font-family: var(--font-mono);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.weight__daily-v--calm {
  color: var(--c-text-muted);
}

.weight__daily-v--warm {
  color: #c96a00;
}

.weight__daily-v--hot {
  color: var(--c-danger);
}

.weight__daily-kg {
  color: var(--c-text-faint);
}

.weight__loop {
  color: #c96a00;
}

/* ── 疲劳 ── */
.fatigue {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 16px;
  border-top: 0.5px solid var(--c-border);
}

.fatigue__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.fatigue__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
}

.fatigue__v {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 300;
  letter-spacing: -0.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.fatigue__v--hot {
  color: var(--c-danger);
}

.fatigue__hint {
  margin-top: 2px;
  font-size: 11px;
  color: var(--c-text-faint);
  line-height: 1.55;
}

/* ── 伤病 ── */
.block__h {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-text-faint);
  margin-bottom: 9px;
}

.prose {
  font-size: 12px;
  line-height: 1.75;
  color: var(--c-text-muted);
  white-space: pre-wrap;
}
