
.wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.block__h {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-text-faint);
  margin-bottom: 9px;
}

.empty {
  font-size: 11.5px;
  color: var(--c-text-faint);
  line-height: 1.6;
}

/* ── 恋爱线：每一条是一段不带框的条目，靠间距分隔 ── */
.lines {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.line {
  padding: 12px 0;
  border-bottom: 0.5px solid var(--c-border);

  &:first-child {
    padding-top: 0;
  }

  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
}

.line__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.line__name {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--c-text);
}

.line__stage {
  font-size: 9.5px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.04);
  white-space: nowrap;
}

.line__stage--cool {
  color: var(--c-text-muted);
}

.line__stage--warm {
  color: #c96a00;
}

.line__stage--hot {
  color: var(--c-primary);
  background: rgba(0, 113, 227, 0.08);
}

.mini {
  display: grid;
  grid-template-columns: 26px 1fr 26px;
  gap: 10px;
  align-items: center;

  & + & {
    margin-top: 6px;
  }
}

.mini__k {
  font-size: 10px;
  color: var(--c-text-faint);
  letter-spacing: 0.02em;
}

.mini__bar {
  height: 2px;
}

.mini__v {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--c-text-muted);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.mini__v--hot {
  color: var(--c-danger);
}

.warn {
  margin-top: 8px;
  font-size: 10.5px;
  color: var(--c-danger);
  letter-spacing: 0.01em;
}

/* ── 关系网：一行一个人，立场用最淡的胶囊 ── */
.rel {
  display: flex;
  flex-direction: column;
}

.rel__row {
  display: grid;
  grid-template-columns: 1fr auto 54px 22px;
  gap: 9px;
  align-items: center;
  padding: 8px 0;
  border-bottom: 0.5px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.rel__name {
  font-size: 12px;
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tag {
  font-size: 9.5px;
  padding: 1px 7px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.04);
  white-space: nowrap;
}

.tag--ok {
  color: #248a3d;
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--bad {
  color: var(--c-danger);
}

.rel__bar {
  height: 2px;
}

.rel__v {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
