
.wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.hero {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px;
}

.hero__n {
  font-family: var(--font-mono);
  font-size: 40px;
  font-weight: 300;
  letter-spacing: -0.035em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.hero__u {
  font-size: 11px;
  color: var(--c-text-faint);
  letter-spacing: 0.05em;
}

.hero__bar {
  flex: 1 1 100%;
  margin-top: 8px;
  height: 2px;
}

.rows {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.row {
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 14px;
  align-items: baseline;
  padding: 9px 0;
  border-bottom: 0.5px solid var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.row__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
}

.row__v {
  font-size: 12.5px;
  color: var(--c-text);
  line-height: 1.5;
}
