
.ap-scope {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  font-family: var(--font-ui);
  user-select: none;
}

/* ── 折叠态：浮在壁纸上的液态胶囊 ── */
.ap-capsule {
  display: block;
  width: 100%;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.9);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  box-shadow:
    var(--lift),
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.5);
  color: var(--c-text);
  cursor: pointer;
  overflow: hidden;
  transition:
    background 0.2s ease,
    box-shadow 0.25s ease,
    border-radius 0.35s var(--ease);
  -webkit-tap-highlight-color: transparent;
}

.ap-capsule:hover {
  background: rgba(255, 255, 255, 0.92);
  box-shadow:
    var(--lift-hi),
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.6);
}

.ap-capsule--open {
  border-radius: 22px 22px 0 0;
  border-bottom-color: transparent;
  box-shadow: var(--lift);
}

.ap-compact {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  height: 38px;
  padding: 0 15px;
}

.ap-leading,
.ap-trailing {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.ap-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ap-dot--ok {
  background: #34c759;
  box-shadow: 0 0 6px rgba(52, 199, 89, 0.55);
}

.ap-dot--warn {
  background: #ff9500;
  box-shadow: 0 0 6px rgba(255, 149, 0, 0.55);
}

.ap-dot--bad {
  background: #ff3b30;
  box-shadow: 0 0 6px rgba(255, 59, 48, 0.55);
}

.ap-who {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.ap-role {
  font-size: 11px;
  color: var(--c-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ap-clock {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.ap-caret {
  width: 14px;
  height: 14px;
  stroke: var(--c-text-faint);
  stroke-width: 1.8;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
  transition: transform 0.35s var(--ease);
}

.ap-caret--up {
  transform: rotate(180deg);
}

/* ── 展开态：从胶囊下沿长出来的纸片 ── */
.ap-sheet {
  display: grid;
  grid-template-rows: 0fr;
  border: 1px solid rgba(255, 255, 255, 0.9);
  border-top: none;
  border-radius: 0 0 22px 22px;
  background: rgba(255, 255, 255, 0.86);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  box-shadow: var(--lift-hi);
  overflow: hidden;
  opacity: 0;
  transition:
    grid-template-rows 0.42s var(--ease),
    opacity 0.3s ease;
}

.ap-sheet--open {
  grid-template-rows: 1fr;
  opacity: 1;
}

.ap-sheet__inner {
  min-height: 0;
  overflow: hidden;
}

.ap-body {
  padding: 14px 15px 15px;
}

.ap-foot {
  padding: 9px 15px 11px;
  border-top: 1px solid var(--c-border);
}

.ap-foot__hint {
  font-size: 11px;
  color: var(--c-text-muted);
  letter-spacing: 0.01em;
  line-height: 1.5;
}
