
.wrap {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.heat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.heat__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.heat__n {
  font-family: var(--font-mono);
  font-size: 32px;
  font-weight: 300;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.heat__n--hot {
  color: var(--c-danger);
}

.heat__bar {
  margin-top: 4px;
  height: 2px;
}

.tag {
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.04);
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.tag--ok {
  color: #248a3d;
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--warn {
  color: #c96a00;
}

.tag--bad {
  color: var(--c-danger);
}

.crisis {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 6px;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  background: rgba(255, 59, 48, 0.06);
}

.crisis__k {
  font-size: 9.5px;
  letter-spacing: 0.14em;
  color: var(--c-danger);
  opacity: 0.75;
  flex-shrink: 0;
}

.crisis__v {
  font-size: 11.5px;
  color: var(--c-danger);
  line-height: 1.5;
}

.block__h {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-text-faint);
  margin-bottom: 9px;
}

.issues {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.issue {
  font-size: 12px;
  color: var(--c-text);
  padding-left: 12px;
  position: relative;
  line-height: 1.6;

  &::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0.68em;
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: var(--c-text-faint);
  }
}

.fan-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
}

.fan-size {
  font-size: 12.5px;
  color: var(--c-text);
}

.fan-power {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.comp {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 11px 18px;
  margin-top: 15px;
}

.comp__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 4px;
}

.comp__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
}

.comp__v {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.comp__bar {
  height: 2px;
}
