
.wrap {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── 身份：无框发丝线表格 ── */
.grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 18px;
}

.field {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 0;
  border-bottom: 0.5px solid var(--c-border);
}

.field__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
  letter-spacing: 0.04em;
  flex-shrink: 0;
}

.field__v {
  font-size: 12.5px;
  color: var(--c-text);
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.field__v--num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
}

/* ── 区块标题：极小的字，全部大写感，靠字距撑起来 ── */
.block__h {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--c-text-faint);
  margin-bottom: 9px;
}

/* ── 资源层级：整形，一整行给它 ── */
.tier {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-bottom: 13px;
  margin-bottom: 13px;
  border-bottom: 0.5px solid var(--c-border);
}

.tier__v {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.tier__sub {
  font-size: 11px;
  color: var(--c-text-muted);
  line-height: 1.5;
}

.meter {
  display: flex;
  flex-direction: column;
  gap: 5px;

  & + & {
    margin-top: 12px;
  }
}

.meter__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.meter__k {
  font-size: 11px;
  color: var(--c-text-muted);
}

.meter__v {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.prose {
  font-size: 12px;
  line-height: 1.75;
  color: var(--c-text-muted);
  white-space: pre-wrap;
  letter-spacing: 0.01em;
}
